/// edge in this module is stroked with.
pub const STROKE_WIDTH: f32 = 1.0;

// ---------------------------------------------------------------------------
// Type: the `body` block, `assets/styles/defaults.scss:8`
//
// Three sizes and three weights, which are what the shell sets small text, body
// text and headings in. They are scheme-independent: `body` is declared once, on
// the element every page sits in.
// ---------------------------------------------------------------------------

/// `--font-size-xs` -- 12.0 points, small text: a metadata row, a caption (defaults.scss:24).
pub const FONT_SIZE_XS: f32 = 12.0;

/// `--font-size-nm` -- 16.0 points, body: the size `body` itself is set in (defaults.scss:26).
pub const FONT_SIZE_NM: f32 = 16.0;

/// `--font-size-xl` -- 24.0 points, headings: the 1.5rem the page header's `text-2xl` also resolves to (defaults.scss:29).
pub const FONT_SIZE_XL: f32 = 24.0;

/// `--font-weight-regular` -- 400, body's `font-weight` (defaults.scss:34).
pub const FONT_WEIGHT_REGULAR: u16 = 400;

/// `--font-weight-text` -- 500, the weight the whole interface is set in (defaults.scss:35 (via --font-weight-medium, declared at defaults.scss:39)).
pub const FONT_WEIGHT_TEXT: u16 = 500;

/// `--font-weight-heading` -- 800, headings and titles (defaults.scss:37 (via --font-weight-extrabold, declared at defaults.scss:40)).
pub const FONT_WEIGHT_HEADING: u16 = 800;

// ---------------------------------------------------------------------------
// Motion: the transitions the sheets declare and this shell animates
//
// Sources:
//   `assets/styles/classes.scss:193`
//   `ui/src/styles/tailwind-utilities.css:70`
//   `ui/src/styles/tailwind-utilities.css:31`
// Durations are in milliseconds and easings are cubic-beziers, because that is
// what a tween needs. Each constant names the rule it was read from, and the
// table at the end carries the same numbers with their property.
// ---------------------------------------------------------------------------

/// A cubic-bezier as the stylesheet names it. `curve` is `(x1, y1, x2, y2)`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Easing {
    /// The name the sheet uses: `ease-in-out`, `--ease-out-expo`, or the bezier
    /// spelled out where the sheet spells it out.
    pub name: &'static str,
    /// The four control points, ready for a cubic-bezier evaluator.
    pub curve: [f32; 4],
}

/// CSS's `ease-in-out`, named by the transitions below (`assets/styles/classes.scss:193`) and
/// transcribed from the specification rather than from this tree.
pub const EASE_IN_OUT: Easing = Easing {
    name: "ease-in-out",
    curve: [0.42, 0.0, 0.58, 1.0],
};

/// `--ease-out-expo`, declared at `ui/src/styles/tailwind-utilities.css:2`.
pub const EASE_OUT_EXPO: Easing = Easing {
    name: "--ease-out-expo",
    curve: [0.16, 1.0, 0.3, 1.0],
};

/// The curve written inline at `ui/src/styles/tailwind-utilities.css:31`, on the action bar whose
/// transition names it.
pub const EASE_FLOATING_BAR: Easing = Easing {
    name: "cubic-bezier(0.15, 1.4, 0.64, 0.96)",
    curve: [0.15, 1.4, 0.64, 0.96],
};

/// Every easing above, for `Theme::easing`.
pub const EASINGS: &[Easing] = &[
    EASE_IN_OUT,
    EASE_OUT_EXPO,
    EASE_FLOATING_BAR,
];

/// `scale 0.05s ease-in-out`
/// -- the press: every clickable scales to 0.95 while held (`assets/styles/classes.scss:193`).
pub const PRESS_MS: u32 = 50;

/// `filter 0.2s ease-in-out`
/// -- a pointer arriving on a control, which the reference does with `filter: brightness()` (`assets/styles/classes.scss:193`).
pub const HOVER_MS: u32 = 200;

/// `outline 0.2s ease-in-out`
/// -- the focus outline (`assets/styles/classes.scss:193`).
pub const OUTLINE_MS: u32 = 200;

/// `opacity 0.5s ease-in-out`
/// -- a clickable fading in or out (`assets/styles/classes.scss:193`).
pub const FADE_MS: u32 = 500;

/// `opacity 0.125s var(--ease-out-expo)`
/// -- a floating panel appearing (`floating-expand`) (`ui/src/styles/tailwind-utilities.css:70`).
pub const POPOVER_MS: u32 = 125;

/// `transform 0.25s cubic-bezier(0.15, 1.4, 0.64, 0.96)`
/// -- the floating action bar sliding in (`ui/src/styles/tailwind-utilities.css:31`).
pub const FLOATING_BAR_MS: u32 = 250;

/// One transition the reference declares and this shell animates.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Motion {
    /// What moves, as the CSS property is named.
    pub property: &'static str,
    /// How long it takes, in milliseconds.
    pub millis: u32,
    /// The curve it moves on.
    pub easing: Easing,
    /// Where the sheet states it, `vendor/modrinth-app/<file>:<line>`, so a stale
    /// number can be traced to the rule that moved.
    pub source: &'static str,
}

/// Every transition above, with the property it moves.
pub const MOTION: &[Motion] = &[
    Motion {
        property: "scale",
        millis: PRESS_MS,
        easing: EASE_IN_OUT,
        source: "vendor/modrinth-app/assets/styles/classes.scss:193",
    },
    Motion {
        property: "filter",
        millis: HOVER_MS,
        easing: EASE_IN_OUT,
        source: "vendor/modrinth-app/assets/styles/classes.scss:193",
    },
    Motion {
        property: "outline",
        millis: OUTLINE_MS,
        easing: EASE_IN_OUT,
        source: "vendor/modrinth-app/assets/styles/classes.scss:193",
    },
    Motion {
        property: "opacity",
        millis: FADE_MS,
        easing: EASE_IN_OUT,
        source: "vendor/modrinth-app/assets/styles/classes.scss:193",
    },
    Motion {
        property: "opacity",
        millis: POPOVER_MS,
        easing: EASE_OUT_EXPO,
        source: "vendor/modrinth-app/ui/src/styles/tailwind-utilities.css:70",
    },
    Motion {
        property: "transform",
        millis: FLOATING_BAR_MS,
        easing: EASE_FLOATING_BAR,
        source: "vendor/modrinth-app/ui/src/styles/tailwind-utilities.css:31",
    },
];

impl Theme {
    /// The egui [`Visuals`] this scheme paints with.
    ///
    /// Every field set here is named with the token it comes from; a field egui has
    /// and the reference does not name keeps whatever egui's own base puts there, so
    /// the two schemes differ only where the stylesheet says they differ.
    pub fn colors(&self) -> Visuals {
        let mut visual = if self.DARK_MODE {
            Visuals::dark()
        } else {
            Visuals::light()
        };

        visual.dark_mode = self.DARK_MODE;

        // `body { background-color: var(--color-bg) }` (defaults.scss:10) is the
        // page, and a panel is the page: the reference has one flat background
        // behind its chrome, with cards raised on top of it.
        visual.window_fill = self.BG;
        visual.panel_fill = self.BG;

        // A raised card or panel: `--color-raised-bg`.
        visual.faint_bg_color = self.RAISED_BG;

        // A text input: the reference's `InputFrame` paints `bg-surface-4`, which
        // is the value `--color-button-bg` resolves to in both schemes.
        visual.extreme_bg_color = self.BUTTON_BG;

        // The interface's default text is `--color-base` (defaults.scss:11). A page
        // that wants `SECONDARY` (muted) or `CONTRAST` (a hovered label) sets it on
        // the `RichText` itself: an override is exactly what stops egui's own
        // `weak()` and the widget `fg_stroke` from choosing a colour.
        visual.override_text_color = Some(self.BASE);

        visual.hyperlink_color = self.LINK;
        visual.warn_fg_color = self.ORANGE;
        visual.error_fg_color = self.RED;

        // A popover is `--color-raised-bg` inside
        // `1px solid var(--color-button-border)` at `--radius-md`
        // (classes.scss:752-756). A window in this shell is a page, so only the
        // edge and the radius come from the popover; the fill stays `BG`, which is
        // what the test at the bottom of this file pins.
        visual.window_stroke = Stroke::new(STROKE_WIDTH, self.BUTTON_BORDER);
        visual.window_corner_radius = CornerRadius::same(RADIUS_LG);

        // Text selection: `--color-brand-highlight` inside `--color-brand`.
        visual.selection.bg_fill = self.BRAND_HIGHLIGHT;
        visual.selection.stroke = Stroke::new(STROKE_WIDTH, self.BRAND);

        // A frame or card: `--color-raised-bg` inside a `--color-divider` line.
        visual.widgets.noninteractive.bg_fill = self.RAISED_BG;
        visual.widgets.noninteractive.weak_bg_fill = self.RAISED_BG;
        visual.widgets.noninteractive.bg_stroke = Stroke::new(STROKE_WIDTH, self.DIVIDER);
        visual.widgets.noninteractive.fg_stroke = Stroke::new(STROKE_WIDTH, self.BASE);
        visual.widgets.noninteractive.corner_radius = CornerRadius::same(RADIUS_MD);
        visual.widgets.noninteractive.expansion = 0.0;

        // A button at rest: `--color-button-bg` inside `--color-button-border`, at
        // the `--radius-md` the sheet gives `.btn` (classes.scss:398).
        visual.widgets.inactive.bg_fill = self.BUTTON_BG;
        visual.widgets.inactive.weak_bg_fill = self.BUTTON_BG;
        visual.widgets.inactive.bg_stroke = Stroke::new(STROKE_WIDTH, self.BUTTON_BORDER);
        visual.widgets.inactive.fg_stroke = Stroke::new(STROKE_WIDTH, self.BASE);
        visual.widgets.inactive.corner_radius = CornerRadius::same(RADIUS_MD);
        visual.widgets.inactive.expansion = 0.0;

        // Under the pointer the fill moves by `--hover-brightness` and the text
        // becomes `--color-contrast`.
        visual.widgets.hovered.bg_fill = self.hovered(self.BUTTON_BG);
        visual.widgets.hovered.weak_bg_fill = self.hovered(self.BUTTON_BG);
        visual.widgets.hovered.bg_stroke = Stroke::new(STROKE_WIDTH, self.BUTTON_BORDER);
        visual.widgets.hovered.fg_stroke = Stroke::new(STROKE_WIDTH, self.CONTRAST);
        visual.widgets.hovered.corner_radius = CornerRadius::same(RADIUS_MD);
        visual.widgets.hovered.expansion = 0.0;

        // Pressed. The sheet presses to `brightness(0.8)` against `0.85` on hover
        // (classes.scss:215, :220); one factor is declared (`--hover-brightness`),
        // so the two states share it and the press differs only in its text.
        visual.widgets.active.bg_fill = self.hovered(self.BUTTON_BG);
        visual.widgets.active.weak_bg_fill = self.hovered(self.BUTTON_BG);
        visual.widgets.active.bg_stroke = Stroke::new(STROKE_WIDTH, self.BUTTON_BORDER);
        visual.widgets.active.fg_stroke = Stroke::new(STROKE_WIDTH, self.CONTRAST);
        visual.widgets.active.corner_radius = CornerRadius::same(RADIUS_MD);
        visual.widgets.active.expansion = 0.0;

        // An open menu: raised, with the popover's border and `--color-contrast`.
        visual.widgets.open.bg_fill = self.RAISED_BG;
        visual.widgets.open.weak_bg_fill = self.RAISED_BG;
        visual.widgets.open.bg_stroke = Stroke::new(STROKE_WIDTH, self.BUTTON_BORDER);
        visual.widgets.open.fg_stroke = Stroke::new(STROKE_WIDTH, self.CONTRAST);
        visual.widgets.open.corner_radius = CornerRadius::same(RADIUS_MD);
        visual.widgets.open.expansion = 0.0;

        visual
    }

    /// The fill a control takes under the pointer.
    ///
    /// The reference does this with a filter --
    /// `filter: brightness(var(--hover-brightness))` (`variables.scss:187`, `:407`)
    /// -- and egui has no filters, so the same factor is applied to the colour the
    /// control was going to paint. It darkens in light (0.9) and brightens in dark
    /// (1.25), which is the direction the reference moves a control in each scheme.
    pub fn hovered(&self, fill: Color32) -> Color32 {
        let scale = |channel: u8| -> u8 {
            let scaled = f32::from(channel) * self.HOVER_BRIGHTNESS;
            scaled.round().clamp(0.0, 255.0) as u8
        };
        Color32::from_rgba_unmultiplied(scale(fill.r()), scale(fill.g()), scale(fill.b()), fill.a())
    }

    /// The `--gap-*` ladder in points, `xs, sm, md, lg, xl` (`variables.scss:195-199`).
    pub fn gaps() -> [f32; 5] {
        [GAP_XS, GAP_SM, GAP_MD, GAP_LG, GAP_XL]
    }

    /// The `--radius-*` ladder in whole pixels, `xs, sm, md, lg, xl, max`
    /// (`variables.scss:201-206`), the shape egui's `CornerRadius` takes.
    pub fn radii() -> [u8; 6] {
        [RADIUS_XS, RADIUS_SM, RADIUS_MD, RADIUS_LG, RADIUS_XL, RADIUS_MAX]
    }

    /// The sizes small text, body and headings are set in: `--font-size-xs` (12px,
    /// a metadata row), `--font-size-nm` (16px, the size `body` itself is set in)
    /// and `--font-size-xl` (24px, the 1.5rem the page header's `text-2xl` also
    /// resolves to), from the ladder at `defaults.scss:23-31`.
    pub fn type_sizes() -> [f32; 3] {
        [FONT_SIZE_XS, FONT_SIZE_NM, FONT_SIZE_XL]
    }

    /// The weights: body (`--font-weight-regular`, 400), the interface
    /// (`--font-weight-text`, 500) and headings (`--font-weight-heading`, 800).
    pub fn type_weights() -> [u16; 3] {
        [FONT_WEIGHT_REGULAR, FONT_WEIGHT_TEXT, FONT_WEIGHT_HEADING]
    }

    /// Every transition the reference declares that this shell animates.
    pub fn motion() -> &'static [Motion] {
        MOTION
    }

    /// The easing a transition moves on, by the name the sheet used for it.
    pub fn easing(name: &str) -> Option<Easing> {
        EASINGS.iter().copied().find(|easing| easing.name == name)
    }
}

/// The scheme the launcher opens in: the reference's own default (`color-scheme:
/// dark` at `app-frontend/src/assets/stylesheets/global.scss:45`).
pub fn dark() -> Theme {
    DARK
}

/// The light scheme.
pub fn light() -> Theme {
    LIGHT
}

